<?php
declare(strict_types=1);
use SaleSync\Core\{ApiError,Database,Session};
use SaleSync\Customer\Module;
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__,2);
$config=require $root.'/app/bootstrap.php';
$path=$root.'/storage/feature-tests-'.bin2hex(random_bytes(6)).'/test.sqlite';
$config=array_replace($config,['database'=>$path,'shipping_fee'=>5000]);
$db=new Database($path);$checks=0;
function check(bool $ok,string $label):void {global $checks;if(!$ok)throw new RuntimeException($label);$checks++;}
function fails(int $status,callable $fn,string $label):void {try{$fn();}catch(ApiError $e){check($e->status===$status,$label.' status '.$e->status);return;}throw new RuntimeException($label.' did not fail');}
try {
    check(\SaleSync\Auth\RegistrationDetails::phone(['phone'=>'09171234567'])==='09171234567','Accept exactly 11 digits and preserve leading zero');
    foreach (['0917123456','091712345678','0917abc4567','+639171234567','0917 1234567'] as $invalidPhone) {
        fails(422,fn()=>\SaleSync\Auth\RegistrationDetails::phone(['phone'=>$invalidPhone]),'Reject invalid phone: '.$invalidPhone);
    }
    foreach(glob($root.'/database/migrations/00[1-4]*.sql')as$file)$db->transaction(fn()=>$db->pdo->exec(file_get_contents($file)));
    foreach([['A','a@example.test','customer'],['B','b@example.test','customer'],['Seller','s@example.test','seller']]as$user)$db->run("INSERT INTO users(name,email,role,password_hash,email_verified_at)VALUES(?,?,?,?,'2026-01-01T00:00:00Z')",[...$user,password_hash('Initial1234',PASSWORD_DEFAULT)]);
    $db->run("INSERT INTO seller_profiles(user_id,store_name,approval_status)VALUES(3,'Shop','approved')");
    $db->run("INSERT INTO categories(category_name)VALUES('Test')");
    $db->run("INSERT INTO products(seller_id,category_id,sku,name,price,stock_qty,status)VALUES(1,1,'A','Item',10000,50,'published')");
    $db->run("INSERT INTO product_variants(product_id,variant_id,name)VALUES(1,'std','Standard')");
    $db->run("INSERT INTO addresses(user_id,label,recipient_name,phone,address_text,is_default)VALUES(1,'Home','A','09123456789','Address',1)");
    $db->run("INSERT INTO orders(customer_id,order_number,address_snapshot,subtotal,shipping_fee,total,checkout_key)VALUES(1,'OLD','{}',10000,5000,15000,'legacy-order-key')");
    $db->run("INSERT INTO order_items(order_id,product_id,seller_id,product_name_snapshot,unit_price,quantity,line_total)VALUES(1,1,1,'Old item',10000,1,10000)");
    $db->run('INSERT INTO payments(order_id,amount)VALUES(1,15000)');
    $db->run("INSERT INTO order_status_history(order_id,status)VALUES(1,'pending_payment')");
    $db->migrate(fn()=>$db->pdo->exec(file_get_contents($root.'/database/migrations/005_customer_features.sql')));
    check($db->all('PRAGMA foreign_key_check')===[],'Existing order children survive upgrade');
    check($db->one('SELECT total,merchandise_discount FROM orders WHERE order_id=1')===['total'=>15000,'merchandise_discount'=>0],'Existing paid amount preserved');
    $db->migrate(fn()=>$db->pdo->exec(file_get_contents($root.'/database/migrations/006_checkout_quotes.sql')));
    $m=new Module($config,$db);
    Session::start($config);Session::login(1);
    fails(422,fn()=>$m->auth->changePassword(['current_password'=>'wrong','new_password'=>'NewPassword123','confirm_password'=>'NewPassword123']),'Require old password');
    $before=$_SESSION['csrf'];
    $result=$m->auth->changePassword(['current_password'=>'Initial1234','new_password'=>'NewPassword123','confirm_password'=>'NewPassword123']);
    check($result['changed']&&$_SESSION['csrf']!==$before,'Rotate password session and CSRF');
    check(password_verify('NewPassword123',$db->one('SELECT password_hash FROM users WHERE user_id=1')['password_hash']),'Hash new password');
    $_SESSION['auth_version']=0;check($m->auth->current()===null,'Invalidate old authenticated sessions');Session::login(1,1);
    $m->saved->save(1,1);$m->saved->save(1,1);
    check(count($m->saved->list(1))===1&&$m->saved->list(2)===[],'Saved products persistent and isolated');
    $db->run("UPDATE products SET status='draft'");check(!$m->saved->list(1)[0]['available'],'Unavailable saved product remains removable');
    fails(404,fn()=>$m->saved->save(2,1),'Cannot save unpublished listing');
    $m->saved->remove(1,1);check($m->saved->list(1)===[],'Remove saved product');$db->run("UPDATE products SET status='published'");
    $m->notifications->savePreferences(1,['orders'=>false,'messages'=>false]);
    fails(422,fn()=>$m->notifications->savePreferences(1,['orders'=>'false']),'Strict boolean preferences');
    $queued=$db->one('SELECT COUNT(*) AS n FROM notification_outbox')['n'];
    $m->notifications->notify(1,'Order notice','Always in inbox','Order');
    check($db->one('SELECT COUNT(*) AS n FROM notification_outbox')['n']===$queued,'Opted-out optional email not queued');
    check($db->one("SELECT notification_id FROM notifications WHERE title='Order notice'")!==null,'Essential inbox notice retained');
    $m->notifications->notify(1,'Security notice','Mandatory','Account');
    check($db->one('SELECT COUNT(*) AS n FROM notification_outbox')['n']===$queued+1,'Mandatory account email retained');
    check($m->notifications->preferences(2)['orders'],'Preferences do not affect another customer');
    foreach([['SHOP','shop',1,'fixed',1000],['SITE','platform',null,'percent',10],['SHIP','shipping',null,'fixed',2000]] as $v)$db->run("INSERT INTO vouchers(code,name,scope,seller_id,kind,value,starts_at,expires_at,active)VALUES(?,'Offer',?,?,?,?,'2020-01-01T00:00:00Z','2099-01-01T00:00:00Z',1)",$v);
    foreach([1,2,3]as$id)$m->vouchers->claim(1,$id);
    $m->cart->set(1,1,2);
    $quote=$m->cart->quote(1,null,[1,2,3]);
    check($quote['total']===20100&&$quote['merchandise_discount']===2900&&$quote['shipping_discount']===2000,'Stack shop then platform then shipping discounts in centavos');
    check(array_sum(array_column($quote['items'],'discount_amount'))===2900,'Allocate exact merchandise discounts to order lines');
    fails(422,fn()=>$m->cart->quote(2,null,[1]),'Cannot spend another customer claim');
    fails(422,fn()=>$m->cart->quote(1,null,[1,1]),'Reject duplicate voucher');
    $checkout=['address_id'=>1,'voucher_ids'=>[1,2,3],'quote_token'=>$quote['quote_token']];
    fails(409,fn()=>$m->orders->checkout(1,['address_id'=>1,'voucher_ids'=>[1,2,3]],'missing-quote-checkout'),'Require a reviewed server quote');
    fails(409,fn()=>$m->orders->checkout(1,[...$checkout,'quote_token'=>str_repeat('0',64)],'forged-quote-checkout'),'Reject fabricated quote token');
    $foreign=(new \SaleSync\Customer\CheckoutQuote($db))->issue(2,$quote);
    fails(409,fn()=>$m->orders->checkout(1,[...$checkout,'quote_token'=>$foreign['quote_token']],'foreign-quote-checkout'),'Quote belongs to its customer');
    $expired=$m->cart->quote(1,null,[1,2,3]);
    $db->run('UPDATE checkout_quotes SET expires_at=1 WHERE token_hash=?',[hash('sha256',$expired['quote_token'])]);
    fails(409,fn()=>$m->orders->checkout(1,[...$checkout,'quote_token'=>$expired['quote_token']],'expired-quote-checkout'),'Expired quote requires review');
    $db->run('UPDATE products SET price=11000 WHERE product_id=1');
    fails(409,fn()=>$m->orders->checkout(1,$checkout,'repriced-quote-checkout'),'Price increase requires reconfirmation');
    check($db->one('SELECT COUNT(*) AS n FROM orders')['n']===1 && $db->one('SELECT stock_qty FROM products')['stock_qty']===50 && $db->all('SELECT * FROM voucher_redemptions')===[],'Rejected quote creates no order, reserves no stock and spends no voucher');
    $db->run('UPDATE products SET price=10000 WHERE product_id=1');
    $m->cart->set(1,1,1);
    fails(409,fn()=>$m->orders->checkout(1,$checkout,'quantity-quote-checkout'),'Quantity change requires reconfirmation');
    $m->cart->set(1,1,2);
    $otherShipping=new \SaleSync\Customer\OrderService($db,new \SaleSync\Customer\CartService($db,6000));
    fails(409,fn()=>$otherShipping->checkout(1,$checkout,'shipping-quote-checkout'),'Delivery fee change requires reconfirmation');
    $order=$m->orders->checkout(1,['address_id'=>1,'voucher_ids'=>[1,2,3],'quote_token'=>$quote['quote_token']],'voucher-checkout-0001');
    check($order['total']===20100&&count($order['vouchers'])===3,'Persist discounted order and redemption records');
    check($db->one('SELECT amount FROM payments WHERE order_id=?',[$order['order_id']])['amount']===20100,'Payment equals discounted total');
    check($m->orders->checkout(1,['address_id'=>1,'voucher_ids'=>[1,2,3]],'voucher-checkout-0001')['order_id']===$order['order_id'],'Retry voucher checkout safely');
    $m->cart->set(1,1,1);fails(422,fn()=>$m->cart->quote(1,null,[1]),'Cannot redeem spent voucher twice');
    $db->run("INSERT INTO vouchers(code,name,scope,kind,value,minimum_spend,starts_at,expires_at,active)VALUES('MIN','Minimum','platform','fixed',1000,999999,'2020-01-01T00:00:00Z','2099-01-01T00:00:00Z',1)");$m->vouchers->claim(1,4);
    fails(422,fn()=>$m->cart->quote(1,null,[4]),'Minimum-spend eligibility enforced');
    $db->run("UPDATE vouchers SET expires_at='2021-01-01T00:00:00Z' WHERE voucher_id=4");fails(422,fn()=>$m->vouchers->claim(2,4),'Expired voucher cannot be claimed');
    $thread=$m->messages->open(1,1)['thread_id'];
    check($m->messages->open(1,1)['thread_id']===$thread,'One conversation per customer/store');
    $message=$m->messages->send(1,$thread,['body'=>'Hello shop','client_key'=>'message-request-001']);
    check($m->messages->send(1,$thread,['body'=>'Hello shop','client_key'=>'message-request-001'])===$message,'Message retries do not duplicate');
    fails(409,fn()=>$m->messages->send(1,$thread,['body'=>'Different','client_key'=>'message-request-001']),'Retry key payload conflict');
    fails(404,fn()=>$m->messages->thread(2,$thread),'Private conversation ownership');
    fails(404,fn()=>$m->messages->send(2,$thread,['body'=>'Intruder','client_key'=>'message-request-002']),'Private conversation write ownership');
    $db->run("INSERT INTO customer_messages(thread_id,sender_id,body,client_key)VALUES(?,3,'Seller reply','seller-reply-fixture')",[$thread]);
    check($m->messages->threads(1)[0]['unread']===1,'Unread incoming reply counted');$m->messages->read(1,$thread);
    check($m->messages->threads(1)[0]['unread']===0,'Incoming read state persisted');
    $png='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aX1EAAAAASUVORK5CYII=';
    $file=$m->uploads->save(1,['purpose'=>'return','name'=>'evidence.png','content'=>$png]);
    check($file['media_type']==='image/png','Validate and save private evidence image');
    fails(422,fn()=>$m->uploads->owned(2,[$file['upload_id']],'return'),'Cannot attach another customer evidence');
    fails(422,fn()=>$m->uploads->save(1,['purpose'=>'return','name'=>'bad.php','content'=>base64_encode('<?php echo 1; ?>')]),'Reject executable upload');
    $item=$order['items'][0]['order_item_id'];
    $request=['order_item_id'=>$item,'quantity'=>1,'reason'=>'Damaged item','explanation'=>'The received product was damaged.','solution'=>'return_refund','client_key'=>'return-request-0001','evidence_ids'=>[$file['upload_id']]];
    fails(409,fn()=>$m->returns->submit(1,$request),'Require paid delivery before return');
    $db->run("UPDATE orders SET status='completed' WHERE order_id=?",[$order['order_id']]);$db->run("UPDATE payments SET status='paid' WHERE order_id=?",[$order['order_id']]);
    $db->run("INSERT INTO order_status_history(order_id,status)VALUES(?,'completed')",[$order['order_id']]);
    $case=$m->returns->submit(1,$request);
    check($m->returns->submit(1,$request)===$case,'Return retries are idempotent');
    check($m->returns->list(1)[0]['eligible_amount']===8550,'Refund limit uses actual discounted merchandise amount');
    check($m->returns->list(2)===[],'Customer return cases are private');
    fails(404,fn()=>$m->returns->appeal(2,$case['case_id'],['explanation'=>'Another customer appeal']),'Appeal ownership');
    fails(409,fn()=>$m->returns->appeal(1,$case['case_id'],['explanation'=>'Please reconsider this case']),'Appeal only rejected cases');
    $db->run("UPDATE return_cases SET status='rejected',seller_reply='Review decision' WHERE case_id=?",[$case['case_id']]);
    check($m->returns->appeal(1,$case['case_id'],['explanation'=>'Please reconsider the attached evidence'])['status']==='escalated','Appeal routes to management without issuing refund');
    check($db->one('SELECT status FROM payments WHERE order_id=?',[$order['order_id']])['status']==='paid','Customer cannot execute a refund');
    $duplicate=$request;$duplicate['quantity']=2;$duplicate['client_key']='return-request-0002';$duplicate['evidence_ids']=[];
    fails(409,fn()=>$m->returns->submit(1,$duplicate),'Prevent duplicate unit claims');
    $db->run("UPDATE order_status_history SET created_at='2020-01-01T00:00:00Z' WHERE order_id=? AND status='completed'",[$order['order_id']]);
    $duplicate['quantity']=1;fails(422,fn()=>$m->returns->submit(1,$duplicate),'Return window enforced');
    $application=['store_name'=>'My shop','business_name'=>'My business','business_type'=>'Sole proprietor','contact_name'=>'Customer A','contact_email'=>'a@example.test','phone'=>'09123456789','address_text'=>'123 Test Street','description'=>'Handmade accessories'];
    $app=$m->applications->submit(1,$application);
    check($app['status']==='pending'&&$m->applications->list(2)===[],'Application pending and private');
    fails(409,fn()=>$m->applications->submit(1,$application),'Prevent concurrent applications');
    $db->run("UPDATE seller_applications SET status='needs_information' WHERE application_id=?",[$app['application_id']]);
    check($m->applications->submit(1,$application)['application_id']===$app['application_id'],'Resubmit requested information with history');
    check($db->one('SELECT role FROM users WHERE user_id=1')['role']==='customer'&&$db->one('SELECT seller_id FROM seller_profiles WHERE user_id=1')===null,'Applying never self-promotes customer');
    check($db->all('PRAGMA foreign_key_check')===[],'All new feature records satisfy foreign keys');
    session_write_close();
    echo "PASS: $checks customer feature and upgrade checks.\n";
} catch(Throwable $e) {fwrite(STDERR,'FAIL: '.$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);}
